def transform(grid):
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    mask = {(r-r0, c-c0) for r, c in pts}
    out = [row[:] for row in grid]
    H, W = len(grid), len(grid[0])
    h, w = r1-r0+1, c1-c0+1
    for dr in range(H-h+1):
        for dc in range(W-w+1):
            if all(grid[dr+r][dc+c] == 0 for r, c in mask):
                for r, c in mask:
                    out[dr+r][dc+c] = 2
    return out
